type Counter = { count: Int }

fn Counter.zero() -> Counter {
    Counter { count: 0 }
}

fn reset(c: Counter) -> Counter {
    c.zero()          // ✗ `zero` has no `self`: not an instance method
}

fn reset(c: Counter) -> Counter {
    Counter.zero()    // ✓ a static function is called on the type
}
